// startMock launches the fixture server and returns its base URL.
func startMock(t *testing.T) string {
	t.Helper()
	srv := httptest.NewServer(mockMux())
	t.Cleanup(srv.Close)
	return srv.URL
}
func newClient(mockURL string) *subscription.Client {
	c := subscription.NewClient("1.0.0-test")
	c.HTTP = &http.Client{Timeout: 5 * time.Second}
	c.Backoff = 10 * time.Millisecond
	return c
}

func fixtureSource(url string) model.Source {
	return model.Source{
		ID: "sub_1", Kind: "subscription", Name: "Fix", Enabled: true, URL: url,
	}
}

// ----------------------------------------------------------------------------
// FR-2.3: request headers
// ----------------------------------------------------------------------------

func TestHeadersSentAndHWIDValid(t *testing.T) {
	base := startMock(t)
	c := newClient(base)

	// The /hdr endpoint echoes the request headers as JSON.
	body, _, err := c.Fetch(context.Background(), base+"/hdr", "ABCDEF1234567890ABCD", subscription.DeviceInfo{
		OS: "OpenWrt", OSVersion: "24.10", Model: "BPI-R4",
	})
	if err != nil {
		t.Fatal(err)
	}
	var echo struct {
		Headers map[string][]string `json:"headers"`
		Path    string              `json:"path"`
	}
	if err := json.Unmarshal(body, &echo); err != nil {
		t.Fatal(err)
	}
	h := echo.Headers
	check := func(name, want string) {
		t.Helper()
		if got := h["X-Hwid"][0]; got != want {
			// httptest canonicalizes: check both cases via the map.
			for k, v := range h {
				if strings.EqualFold(k, name) {
					if v[0] != want {
						t.Fatalf("header %s = %q, want %q", name, v[0], want)
					}
					return
				}
			}
			t.Fatalf("header %s = %q, want %q", name, got, want)
		}
	}
	check("X-Hwid", "ABCDEF1234567890ABCD")
	check("X-Device-Os", "OpenWrt")
	check("X-Ver-Os", "24.10")
	check("X-Device-Model", "BPI-R4")
	if ua := echo.Headers["User-Agent"][0]; ua != "WellBoard/1.0.0-test mihomo" {
		t.Fatalf("UA = %q", ua)
	}
	if !hwid.ValidPattern.MatchString("ABCDEF1234567890ABCD") {
		t.Fatal("hwid must satisfy the panel regex")
	}
}

