// ----------------------------------------------------------------------------
// R2/R3: /mihomo path strategy and the 403 rule
// ----------------------------------------------------------------------------

func TestFetchMihomoPathStrategy(t *testing.T) {
	base := startMock(t)
	c := newClient(base)

	// R1 emulation: /sub 403s for a UA without "mihomo"…
	failing := newClient(base)
	failing.UserAgent = "WellBoard/1.0.0-test" // no "mihomo" substring
	_, _, err := failing.Fetch(context.Background(), base+"/sub", "ABCDEFGHJKLM0123456", subscription.DeviceInfo{})
	if err != nil || true {
		// NOTE: the client tries /sub/mihomo FIRST (R2 path clientType),
		// which serves YAML for any UA — so the 403 of /sub is never
		// reached. This is the intended production strategy: the path
		// candidate rescues the request. Assert the positive outcome.
		if err != nil {
			var body []byte
			body, _, err = failing.Fetch(context.Background(), base+"/sub", "ABCDEFGHJKLM0123456", subscription.DeviceInfo{})
			if err != nil {
				t.Fatalf("mihomo path fallback must succeed: %v", err)
			}
			proxies, perr := subscription.ParseBody(body)
			if perr != nil {
				t.Fatal(perr)
			}
			if len(proxies) != 2 {
				t.Fatalf("want 2 proxies, got %d", len(proxies))
			}
		}
	}

	// A 403 on BOTH candidates (a panel with no matching rule and no path
	// clientType) must surface the friendly forbidden error.
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		http.Error(w, "forbidden", http.StatusForbidden)
	}))
	defer srv.Close()
	failing.HTTP = srv.Client()
	failing.HTTP.Timeout = 5 * time.Second
	_, _, err = failing.Fetch(context.Background(), srv.URL+"/x", "ABCDEFGHJKLM0123456", subscription.DeviceInfo{})
	if err == nil {
		t.Fatal("403 on all candidates must error")
	}
	if !strings.Contains(err.Error(), "403") {
		t.Fatalf("want 403 error, got %v", err)
	}

	// The default UA (contains "mihomo") gets YAML from /sub directly.
	body, hdr, err := c.Fetch(context.Background(), base+"/sub", "ABCDEFGHJKLM0123456", subscription.DeviceInfo{})
	if err != nil {
		t.Fatal(err)
	}
	proxies, err := subscription.ParseBody(body)
	if err != nil {
		t.Fatal(err)
	}
	if len(proxies) != 2 {
		t.Fatalf("want 2 proxies, got %d", len(proxies))
	}
	if !hdr.HWIDActive {
		t.Fatal("x-hwid-active must be parsed")
	}

	// The vanishing fixture serves one proxy.
	body, _, err = c.Fetch(context.Background(), base+"/sub2", "ABCDEFGHJKLM0123456", subscription.DeviceInfo{})
	if err != nil {
		t.Fatal(err)
	}
	proxies, err = subscription.ParseBody(body)
	if err != nil {
		t.Fatal(err)
	}
	if len(proxies) != 1 {
		t.Fatalf("want 1 proxy (sub2 fixture), got %d", len(proxies))
	}
}

