func TestFetch404WithoutHWIDIsClearError(t *testing.T) {
	base := startMock(t)
	c := newClient(base)
	// /404-plain has no trailing clientType, so the client first tries
	// /404-plain/mihomo (unknown fixture → 404 without hwid headers) and
	// then /404-plain itself — both 404 without x-hwid → ErrNotFound.
	_, _, err := c.Fetch(context.Background(), base+"/404-plain", "ABCDEFGHJKLM0123456", subscription.DeviceInfo{})
	if err == nil {
		t.Fatal("404 must error")
	}
	if !strings.Contains(err.Error(), "check the link is current") {
		t.Fatalf("404 must produce the friendly hint, got: %v", err)
	}
}

func TestFetch404WithHWIDLimitStatus(t *testing.T) {
	base := startMock(t)
	c := newClient(base)
	_, hdr, err := c.Fetch(context.Background(), base+"/404-hwid", "ABCDEFGHJKLM0123456", subscription.DeviceInfo{})
	if err == nil {
		t.Fatal("404+hwid must error")
	}
	if !strings.Contains(err.Error(), "device limit") {
		t.Fatalf("404+hwid must mention the device limit, got: %v", err)
	}
	// The headers must have been parsed so the UI can show the status.
	if !hdr.HWIDMaxDevices || !hdr.HWIDActive {
		t.Fatalf("hwid headers not parsed: %+v", hdr)
	}
}

