// ----------------------------------------------------------------------------
// Header set contract (5.7.3)
// ----------------------------------------------------------------------------

func TestFetchFullHeaderSet(t *testing.T) {
	base := startMock(t)
	c := newClient(base)
	_, hdr, err := c.Fetch(context.Background(), base+"/announce", "ABCDEFGHJKLM0123456", subscription.DeviceInfo{})
	if err != nil {
		t.Fatal(err)
	}
	if hdr.Announce != "Scheduled maintenance on Sunday" {
		t.Fatalf("announce: %q", hdr.Announce)
	}
	if got := subscription.DecodeMaybeBase64(hdr.Title); got != "Base64 Title" {
		t.Fatalf("title: %q", got)
	}
	if hdr.UpdateInterval != "3600" {
		t.Fatalf("interval: %q", hdr.UpdateInterval)
	}
	if iv, ok := subscription.ParseIntervalSec(hdr.UpdateInterval); !ok || iv != 3600 {
		t.Fatalf("interval parse: %d %v", iv, ok)
	}
}

// ----------------------------------------------------------------------------
// End-to-end updater cycles against the fixtures
// ----------------------------------------------------------------------------

func setupState(t *testing.T, url string) (*store.Store, *model.State) {
	t.Helper()
	dir := t.TempDir()
	st := store.DefaultState()
	st.Sources = []model.Source{fixtureSource(url)}
	stStore := store.New(dir, false)
	if err := stStore.Save(st); err != nil {
		t.Fatal(err)
	}
	return stStore, st
}

func TestEndToEndNormalSubscription(t *testing.T) {
	base := startMock(t)
	stStore, _ := setupState(t, base+"/sub")

	c := newClient(base)
	u := &subscription.Updater{
		Fetcher: c, Store: stStore, HWID: "ABCDEFGHJKLM0123456",
		Device: &subscription.DeviceInfo{OS: "OpenWrt"},
	}
	res, err := u.Update(context.Background())
	if err != nil {
		t.Fatal(err)
	}
	if len(res.Errors) != 0 {
		t.Fatalf("errors: %v", res.Errors)
	}
	if res.Servers["sub_1"] != 2 {
		t.Fatalf("want 2 servers, got %v", res.Servers)
	}

	st, err := stStore.Load()
	if err != nil {
		t.Fatal(err)
	}
	if st.Sources[0].UserInfo == nil || st.Sources[0].UserInfo.Total != 107374182400 {
		t.Fatalf("userinfo: %+v", st.Sources[0].UserInfo)
	}
	if st.Sources[0].HWIDStatus == nil || !st.Sources[0].HWIDStatus.Active {
		t.Fatalf("hwid status: %+v", st.Sources[0].HWIDStatus)
	}
	if len(st.Servers) != 2 {
		t.Fatalf("servers: %d", len(st.Servers))
	}
}

func TestEndToEndNetworkFailureKeepsServers(t *testing.T) {
	base := startMock(t)
	stStore, st := setupState(t, base+"/sub")

	// Seed two servers via a successful round.
	c := newClient(base)
	u := &subscription.Updater{Fetcher: c, Store: stStore, HWID: "ABCDEFGHJKLM0123456"}
	if _, err := u.Update(context.Background()); err != nil {
		t.Fatal(err)
	}
	st, err := stStore.Load()
	if err != nil {
		t.Fatal(err)
	}
	if len(st.Servers) != 2 {
		t.Fatalf("seed failed: %d servers", len(st.Servers))
	}

	// Now point the source at a dead server (connection refused).
	st.Sources[0].URL = "http://127.0.0.1:1/sub"
	if err := stStore.Save(st); err != nil {
		t.Fatal(err)
	}
	res, err := u.Update(context.Background())
	if err != nil {
		t.Fatal(err)
	}
	if len(res.Errors) != 1 {
		t.Fatalf("want 1 error, got %v", res.Errors)
	}
	st, err = stStore.Load()
	if err != nil {
		t.Fatal(err)
	}
	if len(st.Servers) != 2 {
		t.Fatalf("network failure must keep old servers (5.7.4): %d", len(st.Servers))
	}
	for _, s := range st.Servers {
		if s.Stale {
			t.Fatal("servers must not go stale on a network error")
		}
	}
	if st.Sources[0].LastError == nil {
		t.Fatal("last_error must be recorded")
	}
}

func TestEndToEndVanishedServerGoesStale(t *testing.T) {
	base := startMock(t)
	// /sub serves NL-1 + NL-2; /sub2 serves only NL-1.
	stStore, _ := setupState(t, base+"/sub")

	c := newClient(base)
	u := &subscription.Updater{Fetcher: c, Store: stStore, HWID: "ABCDEFGHJKLM0123456"}
	if _, err := u.Update(context.Background()); err != nil {
		t.Fatal(err)
	}
	st, err := stStore.Load()
	if err != nil {
		t.Fatal(err)
	}
	if len(st.Servers) != 2 {
		t.Fatalf("seed failed: %d", len(st.Servers))
	}

	// Simulate the panel dropping NL-2 (fixture /sub2 has only NL-1).
	st.Sources[0].URL = base + "/sub2"
	if err := stStore.Save(st); err != nil {
		t.Fatal(err)
	}
	if _, err := u.Update(context.Background()); err != nil {
		t.Fatal(err)
	}
	st, err = stStore.Load()
	if err != nil {
		t.Fatal(err)
	}
	var stale, live int
	for _, s := range st.Servers {
		if s.Stale {
			stale++
		} else {
			live++
		}
	}
	if stale != 1 || live != 1 {
		t.Fatalf("want 1 stale + 1 live, got %d/%d", stale, live)
	}

	// Two more rounds → the stale server is deleted (5.7.5).
	for i := 0; i < 2; i++ {
		if _, err := u.Update(context.Background()); err != nil {
			t.Fatal(err)
		}
	}
	st, err = stStore.Load()
	if err != nil {
		t.Fatal(err)
	}
	if len(st.Servers) != 1 {
		t.Fatalf("stale server must be dropped after 3 updates: %d", len(st.Servers))
	}
	if st.Servers[0].Stale {
		t.Fatal("survivor must be live")
	}
}

