// ----------------------------------------------------------------------------
// Retry policy
// ----------------------------------------------------------------------------

func TestFetchRetriesOnNetworkError(t *testing.T) {
	var hits int
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		hits++
		// Fail the first attempt, succeed afterwards.
		if hits <= 1 {
			if hj, ok := w.(http.Hijacker); ok {
				if conn, _, err := hj.Hijack(); err == nil {
					conn.Close()
					return
				}
			}
		}
		fmt.Fprint(w, "trojan://pass123@9.8.7.6:443?sni=tro.example.com#TR1\n")
	}))
	defer srv.Close()

	c := newClient(srv.URL)
	_, _, err := c.Fetch(context.Background(), srv.URL+"/x", "ABCDEFGHJKLM0123456", subscription.DeviceInfo{})
	if err != nil {
		t.Fatalf("retry must recover: %v", err)
	}
	if hits != 2 {
		t.Fatalf("want 2 requests (1 fail + 1 retry), got %d", hits)
	}
}

func TestFetchNoRetryOn404(t *testing.T) {
	var hits int
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		hits++
		http.Error(w, "not found", http.StatusNotFound)
	}))
	defer srv.Close()

	c := newClient(srv.URL)
	// URL already carries a clientType segment → single candidate, no
	// /mihomo duplicate.
	_, _, err := c.Fetch(context.Background(), srv.URL+"/x/mihomo", "ABCDEFGHJKLM0123456", subscription.DeviceInfo{})
	if err == nil {
		t.Fatal("404 must error")
	}
	if hits != 1 {
		t.Fatalf("404 must not be retried: %d requests", hits)
	}
}

func TestFetchTimeout(t *testing.T) {
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		time.Sleep(3 * time.Second)
	}))
	defer srv.Close()

	c := subscription.NewClient("test")
	c.HTTP = &http.Client{Timeout: 200 * time.Millisecond}
	c.Backoff = 5 * time.Millisecond
	start := time.Now()
	_, _, err := c.Fetch(context.Background(), srv.URL+"/slow/mihomo", "ABCDEFGHJKLM0123456", subscription.DeviceInfo{})
	if err == nil {
		t.Fatal("timeout must error")
	}
	if elapsed := time.Since(start); elapsed > 2*time.Second {
		t.Fatalf("timeouts must be quick: %v", elapsed)
	}
}

// Ensure base64 helper parity with the mock fixture encoding.
func TestBase64FixtureParity(t *testing.T) {
	s := "hello"
	if base64.StdEncoding.EncodeToString([]byte(s)) != "aGVsbG8=" {
		t.Fatal("parity broken")
	}
}
